</head>
<body class="flex flex-col h-screen">

 <!-- Header -->
 <header class="bg-white/90 backdrop-blur-md border-b border-slate-200/80 px-6 py-3.5 flex items-center justify-between z-10">
 <div class="flex items-center gap-3">
 <div class="w-10 h-10 rounded-xl bg-gradient-to-tr from-indigo-600 via-purple-600 to-pink-500 flex items-center justify-center shadow-md text-white">
 <i data-lucide="bot" class="w-5 h-5"></i>
 </div>
 <div>
 <div class="flex items-center gap-2">
 <h1 class="text-base font-bold text-slate-900">BBB AI Assistant</h1>
 <span class="inline-flex items-center px-2 py-0.5 rounded-full text-[10px] font-semibold bg-emerald-50 text-emerald-600 border border-emerald-200">
 פעיל
 </span>
 </div>
 <p id="modelInfo" class="text-xs text-slate-500 font-mono mt-0.5">Meta‑Llama‑3.1‑70B‑Instruct</p>
 </div>
 </div>

 <div class="flex items-center gap-2">
 <button id="clearBtn" title="נקה שיחה" class="p-2 rounded-xl text-slate-500 hover:text-rose-600 hover:bg-rose-50 transition-colors">
 <i data-lucide="trash-2" class="w-4 h-4"></i>
 </button>
 <button id="settingsBtn" title="הגדרות" class="flex items-center gap-1.5 px-3 py-1.5 rounded-xl bg-slate-100 hover:bg-slate-200 text-slate-700 transition-colors text-xs font-semibold border border-slate-200/60">
 <i data-lucide="settings" class="w-3.5 h-3.5"></i>הגדרות
 </button>
 </div>
 </header>

 <!-- Chat Area -->
 <main class="flex-1 overflow-y-auto custom-scroll p-4 flex flex-col gap-4 bg-gradient-to-b from-slate-50 to-slate-100">
 <!-- כאן תתווסף הודעות דינמית -->
 </main>

 <!-- Input Bar -->
 <footer class="border-t border-slate-200/80 bg-white/90 backdrop-blur p-3 flex items-center gap-2">
 <textarea id="promptInput" rows="1" placeholder="כתוב שאלה..." class="flex-1 resize-none rounded-xl border border-slate-300 focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500 px-4 py-2.5 text-sm leading-5 placeholder-slate-400 outline-none transition-colors"></textarea>
 <button id="sendBtn" class="flex items-center gap-1.5 px-4 py-2.5 bg-indigo-600 text-white rounded-xl hover:bg-indigo-700 transition-colors disabled:opacity-50 disabled:cursor-not-allowed">
 <i data-lucide="send" class="w-4 h-4"></i>שלח
 </button>
 </footer>

 <script>
 // אתחול אייקונים
 lucide.createIcons();

 const promptInput = document.getElementById('promptInput');
 const sendBtn = document.getElementById('sendBtn');
 const clearBtn = document.getElementById('clearBtn');
 const chatMain = document.querySelector('main');

 // רינדור Markdown עם החלפת קוד בכפתור הצגה
 function renderMarkdown(md) {
 const html = marked.parse(md, { headerIds: false, mangle: false });
 const tempDiv = document.createElement('div');
 tempDiv.innerHTML = html;

 tempDiv.querySelectorAll('pre').forEach(pre => {
 const codeText = pre.textContent;
 const btn = document.createElement('div');
 btn.className = 'code-toggle';
 btn.dataset.code = codeText;
 btn.textContent = 'הצג קוד';
 pre.replaceWith(btn);
 });
 return tempDiv.innerHTML;
 }

 // הוספת הודעת משתמש
 function addUserMessage(text) {
 const container = document.createElement('div');
 container.className = 'self-end flex items-start gap-3 max-w-full';
 container.innerHTML = `
 <div class="bubble bubble-user">
 <p class="font-medium">${text}</p>
 </div>
 <div class="w-9 h-9 rounded-full bg-indigo-600 flex items-center justify-center text-white shrink-0">
 <i data-lucide="user" class="w-4 h-4"></i>
 </div>
 `;
 chatMain.appendChild(container);
 container.scrollIntoView({ behavior: 'smooth' });
 }

 // הוספת הודעת AI (יוצרת קונטיינר חדש בכל תגובה)
 function addAIMessage(md) {
 // קונטיינר ראשי של ההודעה
 const msgWrapper = document.createElement('div');
 msgWrapper.className = 'self-start flex items-start gap-3 max-w-full';

 // אייקון הבוט
 const avatar = document.createElement('div');
 avatar.className = 'w-9 h-9 rounded-full bg-gradient-to-tr from-blue-600 via-indigo-600 to-sky-400 flex items-center justify-center text-white shrink-0';
 avatar.innerHTML = '<i data-lucide="bot" class="w-4 h-4"></i>';

 // בועת הטקסט עם אינדיקטור טעינה
 const bubble = document.createElement('div');
 bubble.className = 'bubble bubble-ai';
 bubble.innerHTML = `
 <div class="typing-dots flex items-center">
 <span></span><span></span><span></span>
 </div>
 <div class="ai-markdown hidden"></div>
 `;

 msgWrapper.appendChild(avatar);
 msgWrapper.appendChild(bubble);
 chatMain.appendChild(msgWrapper);
 msgWrapper.scrollIntoView({ behavior: 'smooth' });

 const typingIndicator = bubble.querySelector('.typing-dots');
 const aiContent = bubble.querySelector('.ai-markdown');

 // סימולציית טעינה של 1.8 שניות
 setTimeout(() => {
 typingIndicator.classList.add('hidden');
 aiContent.innerHTML = renderMarkdown(md);
 aiContent.classList.remove('hidden');
 attachCodeToggle(); // חיבור אירועי הצגת קוד
 }, 1800);
 }

 // טיפול בלחיצה על כפתור "הצג קוד"
 function attachCodeToggle() {
 document.querySelectorAll('.code-toggle').forEach(elem => {
 elem.onclick = () => {
 const code = elem.dataset.code;
 const visibleDiv = document.createElement('div');
 visibleDiv.className = 'code-visible';
 visibleDiv.textContent = code;
 elem.replaceWith(visibleDiv);
 };
 });
 }

 // שליחת הודעה
 sendBtn.addEventListener('click', () => {
 const text = promptInput.value.trim();
 if (!text) return;
 addUserMessage(text);
 promptInput.value = '';

 // כאן אפשר להחליף ב‑fetch ל‑API אמיתי.
 // כרגע מציגים תשובה מדגמית עם קוד.
 const demoResponse = `**תשובה לדוגמה**\n\n- פריט 1\n- פריט 2\n\n\`\`\`python\nprint("Hello, world!")\n\`\`\``;
 addAIMessage(demoResponse);
 });

 // ניקוי השיחה
 clearBtn.addEventListener('click', () => {
 chatMain.innerHTML = '';
 });

 // שליחה עם Enter (בלי Shift)
 promptInput.addEventListener('keydown', (e) => {
 if (e.key === 'Enter' && !e.shiftKey) {
 e.preventDefault();
 sendBtn.click();
 }
 });
 </script>
</body>
</html>
```

### מה תיקן הקוד
- **קונטיינר הודעת AI נוצר דינמית** בכל שליחה, כך שהודעות קודמות נשמרות ולא נכתבות מעליהן. 
- ה‑`typingIndicator` וה‑`aiContent` משוייכים לכל קונטיינר בנפרד. 
- פונקציית `clearBtn` מרוקנת את כל השיחה כעת בצורה בטוחה. 
- הקוד עדיין מציג כפתור “הצג קוד” שמחליף את הקוד המוסתר בתצוגה קריאה.

### איך להרחיב
- **חיבור ל‑API של מודל AI**: במקום `demoResponse` ניתן לבצע `fetch` ל‑endpoint שלכם, לקבל את הטקסט ולקרוא ל‑`addAIMessage(responseText)`. 
- **הוספת כפתור “הסתר קוד”** אחרי הצגת הקוד על‑ידי יצירת אלמנט נוסף עם אירוע `onclick` שמחזיר את הקוד לכפתור. 
- **תמיכה במצב חשוך**: ניתן להוסיף מחלקת `dark` ל‑`body` ולשנות משתני CSS בהתאם.

הסיבה שהצ'אט לא ענה נובעת מכך שבקוד המקורי לא היה מחובר שום שירות AI אמיתי (הייתה רק סימולציה עם טקסט קבוע), ומודאל ההגדרות (להכנסת מפתח API) לא היה קיים בפועל.

הנה האפליקציה המלאה והמתוקנת הכוללת **חלון הגדרות API מלא** (תמיכה ב-OpenAI / OpenRouter / Groq ועוד), שמירת המפתח ב-`localStorage`, טיפול מלא בשגיאות, והסתרת/הצגת קוד בלחיצה.

