 border-radius:50%;animation:pulse 1.4s infinite ease-in-out;
 }
 .typing-dots span:nth-child(2){animation-delay:-0.7s;}
 .typing-dots span:nth-child(3){animation-delay:-0.35s;}
 @keyframes pulse{
 0%,80%,100%{transform:scale(0.6);opacity:0.4;}
 40%{transform:scale(1.1);opacity:1;}
 }

 .ai-markdown{font-size:.95rem;line-height:1.7;}
 .ai-markdown p{margin-bottom:.6rem;}
 .ai-markdown h1,.ai-markdown h2,.ai-markdown h3{
