 }
 .ai-markdown ul,.ai-markdown ol{margin-right:1.25rem;margin-bottom:.6rem;}
 .ai-markdown li{margin-bottom:.25rem;list-style-type:disc;}
 .ai-markdown code:not(pre code){
 background:#1e293b;color:#38bdf8;padding:.15rem .4rem;border-radius:.375rem;
 border:1px solid #334155;font-size:.85em;direction:ltr;font-family:'JetBrains Mono',monospace;
 }
 .ai-markdown pre{
 background:#020617;border:1px solid #1e293b;border-radius:.5rem;padding:.75rem 1rem;
 overflow-x:auto;direction:ltr;text-align:left;margin:.6rem 0;font-family:'JetBrains Mono',monospace;
 font-size:.85rem;color:#93c5fd;
 }
