<body class="flex flex-col h-screen bg-slate-950 text-slate-100">

 <!-- Header -->
 <header class="bg-slate-900/90 backdrop-blur-md border-b border-slate-800 px-6 py-3.5 flex items-center justify-between z-10 shrink-0">
