 <div class="w-10 h-10 rounded-xl bg-gradient-to-tr from-blue-600 via-sky-500 to-indigo-600 flex items-center justify-center shadow-lg shadow-sky-500/20 text-white">
 <i data-lucide="bot" class="w-5 h-5"></i>
 </div>
 <div>
 <div class="flex items-center gap-2">
 <h1 class="text-base font-bold text-white tracking-wide">BBB AI Assistant</h1>
 <span id="statusBadge" class="inline-flex items-center px-2 py-0.5 rounded-full text-[11px] font-semibold bg-emerald-500/10 text-emerald-400 border border-emerald-500/30">
 מוכן לפעולה
 </span>
 </div>
 <p id="modelDisplay" class="text-xs text-sky-400 font-mono mt-0.5">Llama-3.1-70B</p>
 </div>
 </div>

 <div class="flex items-center gap-2">
 <button id="clearBtn" class="flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium text-slate-300 bg-slate-800/80 hover:bg-slate-700/80 border border-slate-700 rounded-lg transition-all">
