 <textarea id="userInput" rows="1" placeholder="הקלד הודעה..."
 class="flex-1 resize-none rounded-lg border border-slate-700 bg-slate-800/60 px-4 py-2 text-sm text-slate-100 placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all"></textarea>
 <button type="submit" id="sendBtn"
 class="flex items-center gap-1.5 px-4 py-2 bg-blue-600 hover:bg-blue-500 text-sm font-medium text-white rounded-lg shadow-md shadow-blue-600/30 transition-all disabled:opacity-50 disabled:pointer-events-none">
 <i data-lucide="send" class="w-4 h-4"></i>
 שלח
