 </footer>

 <!-- Settings Modal -->
 <dialog id="settingsModal" class="rounded-xl bg-slate-800 text-slate-100 border border-slate-700 w-full max-w-md">
 <form method="dialog" class="flex flex-col gap-4 p-6">
 <h2 class="text-lg font-semibold text-sky-400">הגדרות</h2>

 <label class="flex flex-col gap-1">
 <span class="text-sm text-slate-300">דגם</span>
 <select id="modelSelect" class="rounded-md bg-slate-700 text-slate-100 border border-slate-600 focus:outline-none focus:ring-2 focus:ring-blue-500">
 <option value="llama-3.1-70b">Llama 3.1 70B</option>
 <option value="llama-3.1-8b">Llama 3.1 8B</option>
 <option value="gemma-2b">Gemma 2B</option>
 </select>
 </label>

 <label class="flex flex-col gap-1">
 <span class="text-sm text-slate-300">טמפרטורה</span>
 <input type="range" id="tempSlider" min="0" max="1" step="0.05" value="0.7"
 class="w-full">
 <output id="tempValue" class="text-sm text-slate-400">0.7</output>
 </label>

 <div class="flex justify-end gap-2 pt-2">
 <button type="reset" class="px-4 py-2 text-sm text-slate-300 bg-slate-700 rounded hover:bg-slate-600">אפס</button>
 <button type="submit" class="px-4 py-2 text-sm font-medium text-white bg-blue-600 rounded hover:bg-blue-500">שמור</button>
 </div>
 </form>
 </dialog>

 <script type="module">
 import { Lucide } from "https://cdn.jsdelivr.net/npm/lucide@latest";
 Lucide.createIcons();

 const chatContainer = document.getElementById('chatContainer');
 const chatForm = document.getElementById('chatForm');
 const userInput = document.getElementById('userInput');
 const sendBtn = document.getElementById('sendBtn');
 const clearBtn = document.getElementById('clearBtn');
 const statusBadge = document.getElementById('statusBadge');
 const modelDisplay = document.getElementById('modelDisplay');
 const settingsBtn = document.getElementById('settingsBtn');
 const settingsModal = document.getElementById('settingsModal');
 const modelSelect = document.getElementById('modelSelect');
 const tempSlider = document.getElementById('tempSlider');
 const tempValue = document.getElementById('tempValue');

 // Load saved settings
 const savedModel = localStorage.getItem('selectedModel');
 const savedTemp = localStorage.getItem('temperature');
 if (savedModel) modelSelect.value = savedModel;
 if (savedTemp) {
 tempSlider.value = savedTemp;
 tempValue.textContent = savedTemp;
 }

 const modelNames = {
 'llama-3.1-70b': 'Llama-3.1-70B',
 'llama-3.1-8b': 'Llama-3.1-8B',
 'gemma-2b': 'Gemma-2B'
 };
 function updateModelDisplay() {
 modelDisplay.textContent = modelNames[modelSelect.value] || 'Model';
 }
 updateModelDisplay();

 // Settings handling
 settingsBtn.addEventListener('click', () => settingsModal.showModal());
 settingsModal.addEventListener('close', () => {
 const formData = new FormData(settingsModal.querySelector('form'));
 const model = formData.get('modelSelect') || modelSelect.value;
 const temp = formData.get('tempSlider') || tempSlider.value;
 localStorage.setItem('selectedModel', model);
 localStorage.setItem('temperature', temp);
 modelSelect.value = model;
 tempSlider.value = temp;
 tempValue.textContent = temp;
 updateModelDisplay();
 });
 tempSlider.addEventListener('input', () => {
 tempValue.textContent = tempSlider.value;
 });

 // Helper: create message bubble
 function createMessage(content, role = 'assistant') {
 const wrapper = document.createElement('div');
 wrapper.className = role === 'user' ? 'self-end max-w-[80%]' : 'self-start max-w-[80%]';
 const bubble = document.createElement('div');
 bubble.className = `p-3 rounded-lg ${
 role === 'user' ? 'bg-blue-600/80 text-white' : 'bg-slate-800/80 text-slate-100 border border-slate-700'
 }`;
 const markdown = document.createElement('div');
 markdown.className = 'ai-markdown';
 markdown.innerHTML = content;
 bubble.appendChild(markdown);
 wrapper.appendChild(bubble);
 return wrapper;
 }

 // Simulated streaming (replace with real API later)
 async function streamResponse(prompt) {
 // Tokens לדוגמה – ניתן לשנות לכל טקסט רצוי
 const tokens = ["היי", " ", "איך", " ", "היום", "?", " ", "אני", " ", "מוכן", " ", "לעזור", " ", "בכל", " ", "שאלה", "."];
 let accumulated = "";
 for (let i = 0; i < tokens.length; i++) {
 accumulated += tokens[i];
 // מחזירים הודעה חלקית כדי להראות אפקט זרימה
 const partial = createMessage(accumulated, 'assistant');
 // מוחקים את ההודעה הקודמת אם קיימת
 const last = chatContainer.querySelector('.partial-stream');
 if (last) chatContainer.removeChild(last);
 partial.classList.add('partial-stream');
 chatContainer.appendChild(partial);
 chatContainer.scrollTop = chatContainer.scrollHeight;
 await new Promise(r => setTimeout(r, 120));
 }
 // מחיקת הודעת ה‑partial לפני החזרת הטקסט הסופי
 const lastPartial = chatContainer.querySelector('.partial-stream');
 if (lastPartial) chatContainer.removeChild(lastPartial);
 return accumulated;
 }

 // Form submit – כולל טיפול ב‑try/catch ו‑timeout fallback
 chatForm.addEventListener('submit', async (e) => {
 e.preventDefault();
 const prompt = userInput.value.trim();
 if (!prompt) return;

 // הודעת משתמש
 const userMsg = createMessage(prompt.replace(/</g, '&lt;'), 'user');
 chatContainer.appendChild(userMsg);
 chatContainer.scrollTop = chatContainer.scrollHeight;

 // ניקוי שדה הקלט
 userInput.value = '';
 userInput.focus();

 // מציג placeholder של "טיפת כתיבה"
 const placeholder = document.createElement('div');
 placeholder.className = 'self-start max-w-[80%] flex items-center gap-2 p-3 rounded-lg bg-slate-800/80 text-slate-100 border border-slate-700';
 placeholder.innerHTML = '<div class="typing-dots"><span></span><span></span><span></span></div>';
 chatContainer.appendChild(placeholder);
 chatContainer.scrollTop = chatContainer.scrollHeight;

 // Timeout fallback – 10 שניות
 const timeoutPromise = new Promise((_, reject) => setTimeout(() => reject(new Error('Timeout: לא קיבלתי תשובה מה‑AI')), 10000));

 try {
 const finalContent = await Promise.race([streamResponse(prompt), timeoutPromise]);
 // מחיקת placeholder
 chatContainer.removeChild(placeholder);
 // הודעת עוזר סופית
 const assistantMsg = createMessage(finalContent, 'assistant');
 chatContainer.appendChild(assistantMsg);
 } catch (err) {
 // מחיקת placeholder במצב שגיאה
 chatContainer.removeChild(placeholder);
 const errorMsg = createMessage(`<span class="text-red-400">⚠️ ${err.message}</span>`, 'assistant');
 chatContainer.appendChild(errorMsg);
 console.error(err);
 } finally {
 chatContainer.scrollTop = chatContainer.scrollHeight;
 }
 });

 // ניקוי השיחה
 clearBtn.addEventListener('click', () => {
 chatContainer.innerHTML = '';
 });

 // התאמת גובה textarea
 userInput.addEventListener('input', () => {
 userInput.style.height = 'auto';
 userInput.style.height = `${userInput.scrollHeight}px`;
 });
 </script>
</body>
</html>
