 function createMessage(content, role = 'assistant') {
 const wrapper = document.createElement('div');
 wrapper.className = role === 'user' ? 'self-end max-w-[80%]' : 'self-start max-w-[80%]';
 const bubble = document.createElement('div');
 bubble.className = `p-3 rounded-lg ${
 role === 'user' ? 'bg-blue-600/80 text-white' : 'bg-slate-800/80 text-slate-100 border border-slate-700'
 }`;
 const markdown = document.createElement('div');
 markdown.className = 'ai-markdown';
 markdown.innerHTML = content;
 bubble.appendChild(markdown);
 wrapper.appendChild(bubble);
 return wrapper;
 }

 // ---------- קריאה ל‑SambaNova ----------
 async function callSambaNova(prompt) {
 const apiKey = localStorage.getItem('sambaApiKey');
 if (!apiKey) {
 throw new Error('לא הוגדר מפתח API של SambaNova. הוסף אותו בהגדרות.');
 }

 const endpoint = 'https://api.sambanova.ai/v1/chat/completions';
 const payload = {
 model: modelSelect.value,
 temperature: parseFloat(tempSlider.value),
 messages: [{ role: 'user', content: prompt }]
 };

 const response = await fetch(endpoint, {
 method: 'POST',
 headers: {
 'Content-Type': 'application/json',
 'Authorization': `Bearer ${apiKey}`
 },
 body: JSON.stringify(payload)
 });

 if (!response.ok) {
 const err = await response.text();
 throw new Error(`שגיאת API: ${response.status} – ${err}`);
 }

 const data = await response.json();
 return data.choices?.[0]?.message?.content || 'אין תשובה מה‑API.';
 }

 // ---------- שליחת הודעה ----------
 chatForm.addEventListener('submit', async (e) => {
 e.preventDefault();
 const prompt = userInput.value.trim();
 if (!prompt) return;

 // הודעת משתמש
 const userMsg = createMessage(prompt.replace(/</g, '&lt;'), 'user');
 chatContainer.appendChild(userMsg);
 chatContainer.scrollTop = chatContainer.scrollHeight;

 userInput.value = '';
 userInput.focus();

 // placeholder "טיפת כתיבה"
 const placeholder = document.createElement('div');
 placeholder.className = 'self-start max-w-[80%] flex items-center gap-2 p-3 rounded-lg bg-slate-800/80 text-slate-100 border border-slate-700';
 placeholder.innerHTML = '<div class="typing-dots"><span></span><span></span><span></span></div>';
 chatContainer.appendChild(placeholder);
 chatContainer.scrollTop = chatContainer.scrollHeight;

 const timeoutPromise = new Promise((_, reject) => setTimeout(() => reject(new Error('Timeout: לא קיבלתי תשובה מה‑API')), 12000));

 try {
 const finalContent = await Promise.race([callSambaNova(prompt), timeoutPromise]);
 chatContainer.removeChild(placeholder);
 const assistantMsg = createMessage(finalContent, 'assistant');
 chatContainer.appendChild(assistantMsg);
 } catch (err) {
 chatContainer.removeChild(placeholder);
 const errorMsg = createMessage(`<span class="text-red-400">⚠️ ${err.message}</span>`, 'assistant');
 chatContainer.appendChild(errorMsg);
 console.error(err);
 } finally {
 chatContainer.scrollTop = chatContainer.scrollHeight;
 }
 });

 // ---------- ניקוי השיחה ----------
 clearBtn.addEventListener('click', () => {
 chatContainer.innerHTML = '';
 });

 // ---------- התאמת גובה textarea ----------
 userInput.addEventListener('input', () => {
 userInput.style.height = 'auto';
 userInput.style.height = `${userInput.scrollHeight}px`;
 });
 </script>
</body>
