 <div id="root"></div>
 <script src="https://unpkg.com/react@18/umd/react.development.js" crossorigin></script>
 <script src="https://unpkg.com/react-dom@18/umd/react-dom.development.js" crossorigin></script>
 <script src="https://unpkg.com/@babel/standalone/babel.min.js"></script>
 <script type="text/babel">
 // file: index.tsx
 const GROQ_API_KEY = 'YOUR_GROQ_API_KEY'; // החלף במפתח שלך
 const GROQ_API_URL = 'https://api.groq.com/openai/v1/chat/completions';

 interface Message {
 id: number;
 text: string;
 sender: 'user' | 'ai';
 }

 const ChatApp = () => {
 const [messages, setMessages] = React.useState<Message[]>([]);
 const [input, setInput] = React.useState('');
 const [isLoading, setIsLoading] = React.useState(false);
 const messagesEndRef = React.useRef(null);

 const scrollToBottom = () => {
 messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
 };

 React.useEffect(() => {
 scrollToBottom();
 }, [messages]);

 const handleSendMessage = async () => {
 if (!input.trim()) return;

 const newUserMessage: Message = {
 id: Date.now(),
 text: input,
 sender: 'user',
 };

 setMessages([...messages, newUserMessage]);
 setInput('');
 setIsLoading(true);

 try {
 const response = await fetch(GROQ_API_URL, {
 method: 'POST',
 headers: {
 'Content-Type': 'application/json',
 'Authorization': `Bearer ${GROQ_API_KEY}`,
 },
 body: JSON.stringify({
 model: 'llama3',
 messages: [{ role: 'user', content: input }],
 }),
 });

 const data = await response.json();
 const aiResponse = data.choices[0].message.content;

 const newAiMessage: Message = {
 id: Date.now() + 1,
 text: aiResponse,
 sender: 'ai',
 };

 setMessages((prev) => [...prev, newAiMessage]);
 } catch (error) {
 console.error('שגיאה בתקשורת עם ה-API:', error);
 setMessages((prev) => [
 ...prev,
 {
 id: Date.now() + 1,
 text: 'אירעה שגיאה בתקשורת עם השרת.',
 sender: 'ai',
 },
 ]);
 } finally {
 setIsLoading(false);
 }
 };

 return (
 <div className="chat-container">
 <div className="chat-header">BIRGSOL AI צ'אט</div>
 <div className="chat-messages">
 {messages.map((msg) => (
 <div
 key={msg.id}
 className={`message ${msg.sender}-message`}
 >
 {msg.text}
 </div>
 ))}
 {isLoading && <div className="loading">טוען תגובה...</div>}
 <div ref={messagesEndRef} />
 </div>
 <div className="chat-input">
 <input
 type="text"
 value={input}
 onChange={(e) => setInput(e.target.value)}
 onKeyPress={(e) => e.key === 'Enter' && handleSendMessage()}
 placeholder="הקלד הודעה..."
 disabled={isLoading}
 />
 <button onClick={handleSendMessage} disabled={isLoading}>
 שלח
 </button>
 </div>
 </div>
 );
 };

 const root = ReactDOM.createRoot(document.getElementById('root'));
 root.render(<ChatApp />);
 </script>
</body>
</html>
```

### מה האפליקציה עושה:
- **צ'אט אינטראקטיבי**: משתמשים יכולים לשלוח הודעות ולקבל תגובות מודל ה-Llama 3 דרך Groq API.
- **עיצוב רספונסיבי**: מתאים למסכים קטנים וגדולים.
- **אחסון מקומי**: ניתן להוסיף אחסון ב-localStorage לשימור שיחות (לא כלול כאן).
- **ניהול מצבים**: מציג מצבי טעינה ושגיאה.

### איך להרחיב:
1. **הוסף אחסון מקומי**: שמור שיחות ב-localStorage עם `localStorage.setItem` ו-`getItem`.
2. **הוסף היסטוריית שיחות**: צור כפתור "שיחות קודמות" עם רשימת שיחות נשמרות.
3. **שפר את העיצוב**: הוסף אנימציות CSS מתקדמות או ספריית UI כמו Material-UI.

דוד, איך נראה לך? רוצה להוסיף פיצ'ר מסוים או לשנות משהו בעיצוב?

היי דוד, הנה קוד פשוט של טיימר ב‑JavaScript עם ממשק HTML. אפשר לשים את הקובץ במחשב ולפתוח בדפדפן – הטיימר יתחיל, יעצור ויראה כמה זמן עבר.

```html
<!DOCTYPE html>
<html lang="he">
<head>
 <meta charset="UTF-8">
 <title>טיימר פשוט</title>
 <style>
 body { font-family: Arial, sans-serif; text-align: center; margin-top: 50px; }
 #display { font-size: 2em; margin: 20px; }
 button { font-size: 1em; padding: 10px 20px; margin: 5px; }
 </style>
</head>
<body>

<h1>טיימר</h1>
<div id="display">00:00:00</div>

<button id="startBtn">התחל</button>
<button id="pauseBtn">הפסק</button>
<button id="resetBtn">אפס</button>

<script>
 let startTime = 0; // מתי התחיל הטיימר (ב‑ms)
 let elapsed = 0; // זמן שעבר (ב‑ms)
 let timerInterval; // מזהה ה‑setInterval

 const display = document.getElementById('display');
 const startBtn = document.getElementById('startBtn');
 const pauseBtn = document.getElementById('pauseBtn');
 const resetBtn = document.getElementById('resetBtn');

 function updateDisplay() {
 const total = elapsed + (Date.now() - startTime);
 const secs = Math.floor(total / 1000) % 60;
 const mins = Math.floor(total / (1000 * 60)) % 60;
 const hrs = Math.floor(total / (1000 * 60 * 60));

 const format = n => n.toString().padStart(2, '0');
 display.textContent = `${format(hrs)}:${format(mins)}:${format(secs)}`;
 }

 startBtn.onclick = () => {
 if (!timerInterval) {
 startTime = Date.now();
 timerInterval = setInterval(updateDisplay, 250);
 }
 };

 pauseBtn.onclick = () => {
 if (timerInterval) {
 clearInterval(timerInterval);
 timerInterval = null;
 elapsed += Date.now() - startTime;
 }
 };

 resetBtn.onclick = () => {
 clearInterval(timerInterval);
 timerInterval = null;
 startTime = 0;
 elapsed = 0;
 display.textContent = '00:00:00';
 };
</script>

</body>
</html>
```

**איך זה עובד?** 
- כשולחים “התחל” – מתחלפת השעה הנוכחית ל‑`startTime` וה‑`setInterval` מרענן את המסך כל רבע שנייה. 
- “הפסק” עוצר את ה‑interval ומוסיף את הזמן שעבר למשתנה `elapsed`. 
- “אפס” מנקה הכל ומחזיר את המסך ל‑00:00:00.

אם תרצה גרסה בשפה אחרת (Python, C#, וכו') – רק תגיד! 🚀

