### `app.js`
```javascript
// app.js – מודול ES2023
const form = document.getElementById('calc-form');
const resultSection = document.getElementById('result-section');
const resultText = document.getElementById('result-text');
const resetBtn = document.getElementById('reset-button');

const errorSection = document.getElementById('error-section');
const errorText = document.getElementById('error-text');
const errorCloseBtn = document.getElementById('error-close');

/**
 * מציג הודעת שגיאה למשתמש.
 * @param {string} message - טקסט השגיאה.
 */
function showError(message) {
 errorText.textContent = message;
 errorSection.classList.remove('hidden');
 resultSection.classList.add('hidden');
}

/**
 * מסתיר את אזור השגיאה.
 */
function hideError() {
 errorSection.classList.add('hidden');
}

/**
 * מציג תוצאה.
 * @param {number} value - ערך החישוב.
 */
function showResult(value) {
 resultText.textContent = `התוצאה: ${value}`;
 resultSection.classList.remove('hidden');
 errorSection.classList.add('hidden');
}

/**
 * מאפס את הטופס והצגת תוצאות/שגיאות.
 */
function resetCalculator() {
 form.reset();
 resultSection.classList.add('hidden');
 hideError();
 // החזרת הפוקוס לשדה הראשון לשיפור נגישות
 document.getElementById('operand-a').focus();
}

/**
 * ממיר מחרוזת למספר, כולל טיפול במקומות עשרוניים.
 * @param {string} str
 * @returns {number|null}
 */
function parseNumber(str) {
 // החלפת פסיק בנקודה למספרים עם עשרוני (שימוש נפוץ בעברית)
 const normalized = str.replace(',', '.').trim();
 if (normalized === '') return null;
 const num = Number(normalized);
 return Number.isNaN(num) ? null : num;
}

/**
 * מבצע את החישוב לפי האופרטור.
 * @param {number} a
 * @param {number} b
 * @param {string} op
 * @returns {number}
 */
function calculate(a, b, op) {
 switch (op) {
 case '+': return a + b;
 case '-': return a - b;
 case '*': return a * b;
 case '/':
 if (b === 0) {
 throw new Error('לא ניתן לחלק באפס.');
 }
 return a / b;
 default:
 throw new Error('אופרטור לא מוכר.');
 }
}

/* אירוע שליחת הטופס */
form.addEventListener('submit', (e) => {
 e.preventDefault(); // מניעת רענון הדף

 const rawA = document.getElementById('operand-a').value;
 const rawB = document.getElementById('operand-b').value;
 const operator = document.getElementById('operator').value;

 const a = parseNumber(rawA);
 const b = parseNumber(rawB);

 // אימות קלט
 if (a === null) {
 showError('הקלט הראשון אינו מספר תקין.');
 return;
 }
 if (b === null) {
 showError('הקלט השני אינו מספר תקין.');
 return;
 }

 try {
 const result = calculate(a, b, operator);
 // עיגול לתוצאה עם 10 ספרות אחרי הנקודה (מונע ערכים ארוכים מדי)
 const rounded = Math.round(result * 1e10) / 1e10;
 showResult(rounded);
 } catch (err) {
 showError(err.message);
 }
});

/* אירועי כפתורים */
resetBtn.addEventListener('click', resetCalculator);
errorCloseBtn.addEventListener('click', hideError);

/* נגישות – אפשרות שליחת הטופס עם Enter על שדה קלט */
['operand-a', 'operand-b'].forEach(id => {
 document.getElementById(id).addEventListener('keydown', (e) => {
 if (e.key === 'Enter') {
 form.requestSubmit();
 }
 });
});
```

